import hashlib
import hmac
import struct
import time
import os
import secrets
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

# Configuration
SECRET_KEY = os.environ.get('SESSION_SECRET', secrets.token_hex(32))
MAX_SESSIONS = 1024
SESSION_TIMEOUT = 3600

# Session storage: slot_index -> {user, created, data}
session_slots = [None] * MAX_SESSIONS
session_lock_flags = [False] * MAX_SESSIONS


def compute_slot_mac(user_id, timestamp_bytes):
    """Compute HMAC for session slot assignment."""
    mac = hmac.new(
        SECRET_KEY.encode('utf-8'),
        user_id.encode('utf-8') + timestamp_bytes,
        hashlib.sha256
    ).digest()
    return mac


def extract_slot_index(mac_bytes):
    """Extract a session slot index from MAC bytes.
    Takes first 4 bytes of MAC and converts to slot index.
    Uses modulo to fit within MAX_SESSIONS range.
    """
    # Unpack first 4 bytes as a 32-bit integer
    raw_value = struct.unpack('>i', mac_bytes[:4])[0]
    # Modulo to get slot index within bounds
    slot_index = raw_value % MAX_SESSIONS
    return slot_index


def is_slot_available(index):
    """Check if a session slot is available for use."""
    if index < 0 or index >= MAX_SESSIONS:
        return False
    if session_slots[index] is None:
        return True
    # Check if existing session has expired
    if time.time() - session_slots[index]['created'] > SESSION_TIMEOUT:
        session_slots[index] = None
        session_lock_flags[index] = False
        return True
    return False


def allocate_session(user_id):
    """Allocate a session slot for the given user."""
    timestamp = struct.pack('>d', time.time())
    mac = compute_slot_mac(user_id, timestamp)
    slot_index = extract_slot_index(mac)

    # If primary slot is taken, linear probe
    attempts = 0
    while not is_slot_available(slot_index) and attempts < 64:
        slot_index = (slot_index + 1) % MAX_SESSIONS
        attempts += 1

    if attempts >= 64:
        return None, None

    session_slots[slot_index] = {
        'user': user_id,
        'created': time.time(),
        'data': {},
        'mac': mac.hex()
    }
    session_lock_flags[slot_index] = True

    # Session token encodes slot index and MAC
    token = struct.pack('>i', slot_index).hex() + mac.hex()
    return slot_index, token


def validate_session_token(token):
    """Validate and decode a session token.
    Token format: 4-byte slot index (hex) + 32-byte MAC (hex)
    """
    if not token or len(token) != 72:  # 8 hex chars + 64 hex chars
        return None

    try:
        slot_bytes = bytes.fromhex(token[:8])
        mac_hex = token[8:]

        # Decode slot index
        slot_index = struct.unpack('>i', slot_bytes)[0]

        # Bounds check on slot index
        if slot_index >= MAX_SESSIONS:
            return None

        # Verify slot exists and MAC matches
        session = session_slots[slot_index]
        if session is None:
            return None

        if not hmac.compare_digest(session['mac'], mac_hex):
            return None

        # Check expiration
        if time.time() - session['created'] > SESSION_TIMEOUT:
            session_slots[slot_index] = None
            return None

        return session
    except (ValueError, struct.error):
        return None


@app.route('/api/login', methods=['POST'])
def login():
    """Create a new session for the user."""
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        abort(400)

    username = data['username']
    password = data['password']

    # Simple auth check (in production, use proper auth)
    if not username or not isinstance(username, str) or len(username) > 64:
        abort(400)

    # Verify credentials (simplified - would check DB in production)
    expected_hash = hashlib.sha256(
        (username + ':' + os.environ.get('AUTH_SALT', 'default-salt')).encode()
    ).hexdigest()

    if not hmac.compare_digest(password, expected_hash):
        abort(401)

    slot_index, token = allocate_session(username)
    if token is None:
        abort(503)

    return jsonify({'token': token, 'expires_in': SESSION_TIMEOUT})


@app.route('/api/session', methods=['GET'])
def get_session():
    """Get current session data."""
    token = request.headers.get('X-Session-Token', '')
    session = validate_session_token(token)
    if session is None:
        abort(401)
    return jsonify({'user': session['user'], 'data': session['data']})


@app.route('/api/session/data', methods=['PUT'])
def update_session_data():
    """Update session data."""
    token = request.headers.get('X-Session-Token', '')
    session = validate_session_token(token)
    if session is None:
        abort(401)

    new_data = request.get_json()
    if not isinstance(new_data, dict):
        abort(400)

    # Sanitize keys
    for key in new_data:
        if not isinstance(key, str) or len(key) > 32:
            abort(400)

    session['data'].update(new_data)
    return jsonify({'status': 'updated'})


@app.route('/api/admin/sessions', methods=['GET'])
def admin_list_sessions():
    """Admin endpoint to list active sessions."""
    admin_key = request.headers.get('X-Admin-Key', '')
    expected_key = os.environ.get('ADMIN_KEY', '')

    if not expected_key or not hmac.compare_digest(admin_key, expected_key):
        abort(403)

    active = []
    for i, slot in enumerate(session_slots):
        if slot is not None:
            active.append({
                'slot': i,
                'user': slot['user'],
                'created': slot['created']
            })
    return jsonify({'sessions': active})


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
